// ❌ OLD: Hardcoding path prefixes and role requirements inside procedural middleware
// easily breaks when routes change or nested controllers are introduced.
export function RoleMiddleware(req: any, res: any, next: any) {
  if (req.path.startsWith('/admin') && req.user?.role !== 'admin') {
    return res.status(403).json({ message: 'Forbidden' });
  }
  next();
}

import { Injectable, CanActivate, ExecutionContext } from '@nestjs/common';
import { Reflector } from '@nestjs/core';

export const Roles = Reflector.createDecorator<string[]>();

@Injectable()
export class RolesGuard implements CanActivate {
  constructor(private reflector: Reflector) {}

  canActivate(context: ExecutionContext): boolean {
    const requiredRoles = this.reflector.getAllAndOverride(Roles, [
      context.getHandler(),
      context.getClass()
    ]);
    if (!requiredRoles) return true; // No roles required -> public

    const request = context.switchToHttp().getRequest();
    const user = request.user;
    return requiredRoles.some((role) => user?.roles?.includes(role));
  }
}

